                    </div>
                  </div>
                </motion.div>

                {/* ========================================================== */}
                {/* BOTTOM CTA - Like a Prayer/Reflection */}
                {/* ========================================================== */}
                <motion.div 
                  variants={fadeInUp}
                  className="mt-8 pt-8 border-t border-gray-100"
                >
                  <div className="bg-gradient-to-br from-maroon-900 to-maroon-800 rounded-2xl p-6 md:p-8 text-center text-white">
